function onlyUnique(value,index,self){return self.indexOf(value)===index}function add_list_cookie(key,val){let a=Cookies.get(key);if(typeof a==="undefined"){Cookies.set(key,","+val,{sameSite:"lax"});return true}else{let items=a.split(",");items.push(val);items=items.filter(onlyUnique);Cookies.set(key,items.join(","),{sameSite:"lax"});return true}}function remove_from_list_cookie(key,val){let a=Cookies.get(key);let items=a.split(",");let indx=items.indexOf(val);if(indx!==-1)items.splice(indx,1);items=items.filter(onlyUnique);Cookies.set(key,items.join(","),{sameSite:"lax"});return true}function get_list_cookie(key){let a=Cookies.get(key);if(typeof a==="undefined"){return[]}else{return a.split(",")}}function get_cookie(key){let a=Cookies.get(key);if(typeof a==="undefined"){return""}else{return a}}function set_cookie(key,value){Cookies.set(key,value,{sameSite:"lax"});return true}function delete_cookie(key){Cookies.remove(key);return true}